-- An invoice can be split into scheduled instalments, each an amount due on a date. They are only
-- a schedule for paying the invoice, not money received, so they go with their invoice.
CREATE TABLE invoice_instalment (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    due_date   DATE           NOT NULL,
    CONSTRAINT invoice_instalment_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE CASCADE,
    CONSTRAINT invoice_instalment_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_instalment_invoice_idx ON invoice_instalment (invoice_id);
-- An instalment is marked paid once it has been settled, so the next one due can be told apart.
ALTER TABLE invoice_instalment ADD COLUMN paid BOOLEAN DEFAULT FALSE NOT NULL;
-- A job can have a start date and an end date; either may be unset. The end may not be before the start.
ALTER TABLE project ADD COLUMN start_date DATE;
ALTER TABLE project ADD COLUMN end_date DATE;
ALTER TABLE project ADD CONSTRAINT project_dates_ordered CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date);
-- A sent invoice that is overdue accrues a late fee: a flat amount for each day past its due date.
-- Existing invoices charge none.
ALTER TABLE invoice ADD COLUMN late_fee_per_day DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_late_fee_per_day_non_negative CHECK (late_fee_per_day >= 0);
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** A scheduled part of an invoice: an amount due on a date. */
export interface Instalment {
  id: number;
  invoiceId: number;
  amount: number;
  /** ISO date (yyyy-MM-dd) the instalment is due. */
  date: string;
  /** Whether the instalment has been paid. */
  paid: boolean;
}

/** The earliest instalment of an invoice still to be paid. */
export interface NextInstalment {
  id: number;
  amount: number;
  /** ISO date (yyyy-MM-dd) it is due. */
  date: string;
  /** Whether its due date has already passed. */
  overdue: boolean;
}

export interface NewInstalment {
  amount: number;
  date: string;
}

@Injectable({ providedIn: 'root' })
export class InstalmentService {
  private readonly http = inject(HttpClient);

  /** An invoice's instalments, earliest due first. */
  list(projectId: number, invoiceId: number): Observable<Instalment[]> {
    return this.http.get<Instalment[]>(`/api/projects/${projectId}/invoices/${invoiceId}/instalments`);
  }

  /** The next instalment due on an invoice, or null when nothing more is due on its plan. */
  next(projectId: number, invoiceId: number): Observable<NextInstalment | null> {
    return this.http.get<NextInstalment | null>(`/api/projects/${projectId}/invoices/${invoiceId}/instalments/next`);
  }

  schedule(projectId: number, invoiceId: number, instalment: NewInstalment): Observable<Instalment> {
    return this.http.post<Instalment>(`/api/projects/${projectId}/invoices/${invoiceId}/instalments`, instalment);
  }

  remove(projectId: number, invoiceId: number, instalmentId: number): Observable<void> {
    return this.http.delete<void>(`/api/projects/${projectId}/invoices/${invoiceId}/instalments/${instalmentId}`);
  }
}
